# Mirrors CaptionLayout.place's snap, sort, trim and drop (app/Sources/CaptionLayout.swift:262-290)
# over the cues of two clips holding the same speech. Ticks are 1/600000 s here only by ratio;
# seconds are used, snapped to a 30 fps grid.
FPS = 30
FRAME = 1 / FPS


def snap(t):
    return round(t * FPS) / FPS


def place(cues):
    placed = []
    for order, (start, end, text, who) in enumerate(cues):
        s, e = snap(max(0, start)), snap(end)
        placed.append([s, max(e, s + FRAME), text, who, order])
    placed.sort(key=lambda c: (c[0], c[4]))
    trimmed = 0
    for i in range(len(placed) - 1):
        if placed[i][1] > placed[i + 1][0] + 1e-9:
            placed[i][1] = placed[i + 1][0]
            trimmed += 1
    kept = [c for c in placed if c[1] - c[0] >= FRAME - 1e-9]
    return kept, trimmed, len(placed) - len(kept)


def stream(who, offset):
    lines = ["so the thing is", "that we never", "really tried it"]
    return [(i * 2 + offset, i * 2 + 2 + offset - 0.05, t, who) for i, t in enumerate(lines)]


for offset in (0.0, 0.1, 0.5):
    cues = stream("camera", 0.0) + stream("mic", offset)
    kept, trimmed, dropped = place(cues)
    print(f"-- mic {offset:.1f} s behind the camera: trimmed {trimmed}, dropped {dropped}")
    for s, e, text, who, _ in kept:
        print(f"   {s:5.2f}-{e:5.2f} ({round((e - s) * FPS):3d} frames) {who:6} {text}")

print("-- a muted clip alone, different speech, nothing else on the timeline at that moment")
kept, trimmed, dropped = place(stream("muted", 0.0))
print(f"   {len(kept)} captions placed, trimmed {trimmed}")

